/** Generates a period per month between the dates, leaving out months already named or overlapped; shows how many were made. */
protected async generate(e: Event): Promise<void> {
  e.preventDefault();
  if (this.generating) return;
  this.generated.set(null);
  this.genError.set(null);
  const sheet = this.session.sheetId();
  if (!sheet) return;
  const from = this.genFrom().trim() || (this.session.sheetToday() ?? '');
  const to = this.genTo().trim();
  if (!DATE.test(from) || !DATE.test(to)) {
    this.genError.set('Enter a from and a to date as yyyy-mm-dd.');
    return;
  }
  if (to < from) {
    this.genError.set('The to-date cannot be before the from-date.');
    return;
  }
  this.generating = true;
  try {
    const made = await this.store.generate(sheet, from, to);
    if (this.session.sheetId() !== sheet) return;
    this.generated.set(made);
  } catch {
    this.genError.set('Could not generate those periods.');
  } finally {
    this.generating = false;
  }
}

/** Adds each pasted line's amount to the person's opening balance for the period, all or none; shows how many went through. */
protected async importOpenings(e: Event): Promise<void> {
  e.preventDefault();
  if (this.importingOpenings) return;
  this.openingsDone.set(null);
  this.openingError.set(null);
  const sheet = this.session.sheetId();
  if (!sheet) return;
  const text = this.openingText();
  const lines = text.split(/\r?\n/).filter((l) => l.trim() !== '');
  if (lines.length === 0) {
    this.openingError.set('Paste at least one line of name,period,amount.');
    return;
  }
  for (const line of lines) {
    const f = line.split(',');
    if (f.length !== 3 || !this.store.list().some((p) => p.name === f[1].trim()) || !AMOUNT.test(f[2].trim())) {
      this.openingError.set(`"${line.trim()}" is not a name, a period on the sheet and an amount of 0.00 or more.`);
      return;
    }
  }
  this.importingOpenings = true;
  try {
    const done = await this.store.importOpenings(sheet, text);
    if (this.session.sheetId() !== sheet) return;
    this.openingsDone.set(done);
    this.openingText.set('');
  } catch {
    this.openingError.set('Could not paste those opening balances: check every line names someone on the sheet.');
  } finally {
    this.importingOpenings = false;
  }
}

/** Generates the fiscal year's twelve monthly periods as generate does; shows how many were made. */
protected async generateFiscalYear(e: Event): Promise<void> {
  e.preventDefault();
  if (this.generating) return;
  this.generated.set(null);
  this.genError.set(null);
  const sheet = this.session.sheetId();
  if (!sheet) return;
  const year = this.fyYear().trim();
  if (!/^\d{4}$/.test(year) || year === '0000' || year === '9999') {
    this.genError.set('Enter a fiscal year as yyyy.');
    return;
  }
  this.generating = true;
  try {
    const made = await this.store.generateFiscalYear(sheet, Number(year));
    if (this.session.sheetId() !== sheet) return;
    this.generated.set(made);
  } catch {
    this.genError.set('Could not generate that fiscal year\'s periods.');
  } finally {
    this.generating = false;
  }
}

